<?php require __DIR__.'/_layout.php';x1_protocol_seed();$db=x1_db();$contracts=$db?x1_db_all('SELECT * FROM protocol_contracts ORDER BY name'):[];$stats=[];if($db)foreach($contracts as $c){$stats[$c['name']]=x1_db_one("SELECT status,tested_at,device_model,android_version,notes FROM android_validation WHERE contract_name=? ORDER BY updated_at DESC LIMIT 1",[$c['name']]);}top(tr('Protocol Observatory','Observatório de Protocolo'));?><section class="card hero"><div class=eyebrow>ENGINEERING CONTROL PLANE</div><h2><?=tr('Contract → transport → evidence → X1 route → Android validation','Contrato → transport → evidência → rota X1 → validação Android')?></h2></section><section class=section><table><tr><th>Contract</th><th>Transport</th><th>Confidence</th><th>Request</th><th>Response</th><th>Stock routing</th><th>X1 endpoint</th><th>Android</th></tr><?php foreach($contracts as $c):$v=$stats[$c['name']]??null;?><tr><td><strong><?=h($c['name'])?></strong><br><span class=muted><?=h($c['evidence'])?></span></td><td><?=h($c['transport'])?></td><td><?=h($c['confidence'])?></td><td><code><?=h($c['request_schema'])?></code></td><td><code><?=h($c['response_schema'])?></code></td><td><?=h($c['stock_routing'])?></td><td><code><?=h($c['x1_endpoint'])?></code></td><td class="<?=($v['status']??'')==='PASS'?'good':'warn'?>"><?=h($v['status']??'PENDING')?><br><span class=muted><?=h($v['tested_at']??'')?></span></td></tr><?php endforeach?></table></section><?php bottom();